# Read all polymorph files and consolidate
polymorph_dir = Path("sulphides_dataset")
all_polymorphs = []

for json_file in sorted(polymorph_dir.glob("*_polymorphs.json")):
    try:
        with open(json_file, 'r') as f:
            file_data = json.load(f)
            # Add composition information
            composition = json_file.stem.replace("_polymorphs", "")
            for item in file_data:
                item['composition'] = composition
            all_polymorphs.extend(file_data)
    except Exception as e:
        print(f"Error reading {json_file}: {e}")

filtered_data = all_polymorphs
print(f"Consolidated {len(all_polymorphs)} polymorphs")
